{
  "primary_meaning": "Spiritual freedom from bondage to sin, death, and the Mosaic law through Christ",
  "primary_basis": [
    "Galatians 5:1",
    "John 8:32-36",
    "2 Corinthians 3:17",
    "Romans 8:2",
    "Romans 6:18"
  ],
  "alternatives": [
    {
      "meaning": "Typological release from physical captivity or debt slavery (Jubilee/messianic liberation) pointing to spiritual freedom",
      "basis": [
        "Leviticus 25",
        "Isaiah 61:1",
        "Luke 4:18-19"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Socio-political or national liberation applied to contemporary oppression",
      "basis": [
        "Exodus narrative",
        "liberation-theology readings of Isaiah and Luke"
      ],
      "prominence": "minority"
    },
    {
      "meaning": "Moral license or freedom to indulge the flesh",
      "basis": [
        "Misreading of Galatians 5:13 and 1 Corinthians 6:12"
      ],
      "prominence": "rare"
    }
  ],
  "has_settled_consensus": true,
  "confidence": "high",
  "notes": "New Testament usage of eleutheria/eleutheros consistently centers on Christ-won spiritual freedom; OT precedents function mainly as types. Political applications exist in some traditions but remain secondary to the spiritual sense in standard biblical interpretation."
}
